 * @return {string}
 */
var reverseVowels = function(s) {
    s=s.split('')
    let i=0, j=s.length-1
    while(i<=j){
        if(/^[aeiou]$/i.test(s[i]) && /^[aeiou]$/i.test(s[j])){
            [s[i],s[j]]=[s[j],s[i]]
            i++
            j--
        }
        else if(/^[aeiou]$/i.test(s[i]) && !/^[aeiou]$/i.test(s[j])){
            j--
        }
        else if(!/^[aeiou]$/i.test(s[i]) && /^[aeiou]$/i.test(s[j])){
            i++
        }
        else {
            i++
            j--
        }
    }
  s=s.join('')
  return s
};

